def rot_custom(m,ang,mode='clamp'):
 out=np.zeros_like(m);th=np.deg2rad(ang)
 for r in range(5):
  for c in range(5):
   y=r-2;x=c-2
   rr=x*np.sin(th)+y*np.cos(th);cc=x*np.cos(th)-y*np.sin(th)
   ri=int(round(rr+2));ci=int(round(cc+2))
   if mode=='clamp':ri=np.clip(ri,0,4);ci=np.clip(ci,0,4)
   if 0<=ri<5 and 0<=ci<5:out[ri,ci]=m[r,c]
 return out
